def wire(v):return (json.dumps(v,sort_keys=True,indent=2,allow_nan=False)+'\n').encode()
def ident(s):return [s.st_dev,s.st_ino,s.st_mode,s.st_uid,s.st_gid,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns]
def read(path):
    s=path.lstat();assert stat.S_ISREG(s.st_mode) and s.st_nlink==1
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
    try:
        assert ident(s)==ident(os.fstat(fd));chunks=[];n=0
        while True:
            b=os.read(fd,1<<20)
            if not b:break
            chunks.append(b);n+=len(b);assert n<=s.st_size
        assert n==s.st_size and ident(s)==ident(os.fstat(fd))==ident(path.lstat())
    finally:os.close(fd)
    b=b''.join(chunks)
    return {'path':str(path),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'git_blob':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest(),'identity':ident(s)},b
def write(path,raw):
    path.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
    with path.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    os.chmod(path,0o600);assert read(path)[1]==raw
